import {registerTranslations} from './localization.js';
export function spectralFunction(img){
 const pairs=[];const t=(a,b)=>{pairs.push([a,b]);return a;};
 const cases=[['light',t('A. LIGHT & SHADOW','A. 光与影'),t('A hand enters a field of light and shadow.','手进入光与影的场域。'),t('Let a small physical gesture shape an ambient response.','让微小的身体动作塑造环境中的回应。')],['memory',t('B. A MEASURE OF FEELING','B. 情感的刻度'),t('A physical gesture becomes a visible measure of personal significance.','通过动作与刻度，让情感的分量获得可感知的度量。'),t('Measure the duration of an embrace, turning time spent into a tangible expression of care.','将测量融入拥抱仪式，以拥抱持续时间承载情感投入，让关怀获得可见的刻度。')],['time',t('C. TIME & RITUAL','C. 时间与仪式'),t('Time becomes a visible, tangible arrangement.','时间成为可见、可触的排列。'),t('Recall a familiar rhythm, rather than simulate a person.','唤起熟悉的生活节律，而非模拟一个人。')]];
 const functions=[
 [t('HOLD & MEASURE','拥抱与测量'),t('Holding begins the ritual. Its duration gives the moment a personal measure; release ends it.','拥抱开启仪式，持续时间成为这一刻的情感刻度，松手结束测量。'),'hold'],
 [t('FLUID AS RESPONSE','流体，承载回应'),t('A gently inclined viewing surface reveals slow fluid movement and reflected light.','微倾的观赏面呈现缓慢的流体运动与反射光。'),'fluid'],
 [t('PROJECT A TRACE','投影，呈现痕迹'),t('A front aperture projects a selected fragment or abstract light cue into the room.','通过前侧孔隙，将选定的片段或抽象光影投射到房间中。'),'projection'],
 [t('RETURN TO A RHYTHM','重访，熟悉的节律'),t('The app links chosen memories to familiar times; scheduled recall remains optional.','应用将选定记忆与熟悉时刻相连；定时重访由用户选择。'),'time']];
 const parts=[
 [t('Viewing surface','流体观赏面'),t('Enclosure integration proposal.','外壳整合方案。')],
 [t('Layer 1 / Electromagnets','第 1 层 / 电磁铁'),t('Mounted beneath the fluid surface.','安装于流体界面下方。')],
 [t('Layer 2 / Micro projector','第 2 层 / 微型投影仪'),t('Front-left lens aligned with the aperture.','左前端镜头对齐出光孔隙。')],
 [t('Layer 3 / Computing + control','第 3 层 / 计算与控制'),t('Mini PC + Arduino Uno + breadboard + MOSFET.','Mini PC＋Arduino Uno＋面包板＋MOSFET。')],
 [t('Photosensitive sensor','光敏传感器'),t('Prototype input for detecting hold duration through light changes.','原型通过光照变化检测拥抱持续时间的输入。')],
 [t('Shell + vented base','外壳与通风底座'),t('Proposed enclosure around the three-layer prototype architecture.','围绕三层原型架构的拟议外壳。')]];
 const diagram=kind=>`<svg viewBox="0 0 180 115" fill="none" stroke="#777" stroke-width="1.3" aria-hidden="true">${kind==='projection'?'<path d="M50 100Q36 57 56 17L139 12Q166 56 150 100Z M52 43h18v22H49"/><rect x="70" y="42" width="67" height="25" rx="2" fill="#e5c689"/><path d="M76 42v25m8-25v25m8-25v25m8-25v25m8-25v25m8-25v25 M60 49h10v14H60z"/><path d="M60 50 4 29v62l56-28" fill="#eecb8644" stroke="#d6ae61"/>':kind==='time'?'<path d="M9 67h160"/><circle cx="24" cy="67" r="6"/><circle cx="88" cy="67" r="6"/><circle cx="152" cy="67" r="6"/><path d="M24 52V35m64 17V22m64 30V35"/>':'<ellipse cx="88" cy="39" rx="48" ry="15"/><path d="M40 39Q21 80 40 99Q89 113 137 99Q151 72 136 39 M43 62Q62 83 81 57"/>'+(kind==='hold'?'<path d="M110 8 86 20 69 39q0 9 9 3l15-14 11 9 29-13 28-12 M82 26l-7-11-28 5"/>':'<path d="M53 38q15-13 28 0t35 0m-43 5q12-11 26 0"/>')}</svg>`;
 const html=`<section class="sf-page fx-page" id="sf-04" aria-labelledby="fx-title"><div class="fr-running"><span>${t('SPECTRAL FLUID / FROM FUNCTIONAL REFERENCES TO SYSTEM','灵韵光谱 / 从功能参考到系统')}</span><span>${t('05 / FUNCTION & STRUCTURE','05 / 功能与结构')}</span></div><header class="fx-header"><h2 id="fx-title">${t('A QUIET RESPONSE, BUILT FROM WITHIN.','安静的回应，源于内部的协作。')}</h2><p>${t('Light, personal traces and remembered rhythms become a tangible experience.','让光、个人痕迹与记忆中的节律成为可感知的体验。')}</p></header><div class="fx-grid"><div class="fx-cases"><h3 class="fr-tag">${t('01 / Functional precedents','01 / 功能案例调研')}</h3>${cases.map(([src,title,obs,reading])=>`<article><h4>${title}</h4><div class="fx-case-row">${img('assets/spectral/function/'+src+'.png',title,'fx-photo fx-'+src)}<div><b>${t('Observed:','观察：')}</b><p>${obs}</p><b>${t('Design reading:','设计解读：')}</b><p>${reading}</p></div></div></article>`).join('')}<small>${t('Reference images from the author’s collection; interpretations are design readings.','参考图片来自作者整理的图集；解读为设计分析。')}</small></div><div class="fx-functions"><h3 class="fr-tag">${t('02 / Functions we propose','02 / 我们提出的功能')}</h3>${functions.map(([title,body,kind],i)=>`<article class="fx-function"><span>0${i+1}</span><div><h4>${title}</h4><p>${body}</p>${i===2?`<b>${t('Continuous outer curve + clear optical opening.','连续的外壳流线 + 通畅的投影出光孔隙。')}</b>`:''}</div>${diagram(kind)}</article>`).join('')}<div class="fx-sequence"><h4>${t('A SIMPLE SEQUENCE','简洁的交互过程')}</h4><div>${[[t('CHOOSE','选择'),t('Select a personal record.','选择个人记录。')],[t('HOLD','捧握'),t('Begin by choice.','自主开启。')],[t('ENCOUNTER','相遇'),t('Fluid and light unfold.','流体与光渐次展开。')],[t('RELEASE','松手'),t('Return to quiet.','回归安静。')]].map(([a,b])=>`<div>${diagram('fluid')}<b>${a}</b><p>${b}</p></div>`).join('')}</div></div><small>${t('A deliberate beginning, a gradual response and a quiet ending.','主动开启、渐进回应、安静结束。')}</small></div><div class="fx-structure"><h3 class="fr-tag">${t('03 / Structure enables the experience','03 / 结构支撑体验')}</h3><div class="fx-assembly">${img('assets/spectral/function/assembly-three-layers-dots.png','Prototype-informed three-layer enclosure assembly','fx-assembly-image')}<ol>${parts.map(([a,b],i)=>`<li><span>0${i+1}</span><div><h4>${a}</h4><p>${b}</p></div></li>`).join('')}</ol></div><aside><b>${t('A recess with a purpose.','凹口，有其功能。')}</b><p>${t('Preserve the flowing silhouette while leaving room for projection.','保持外壳流线，并为投影仪留出出光孔隙。')}</p></aside></div></div><footer class="fx-footer"><b>${t('Form makes the gesture inviting. Structure makes the response possible.','形态邀请交互，结构支撑回应。')}</b><p>${t('DESIGN FOCUS / Clear light path · Layered architecture · Quiet response','设计重点 / 清晰光路 · 分层架构 · 安静回应')}</p><small>${t('From a three-layer prototype to a coherent product form.','从三层实体原型，推导完整的产品形态。')}</small></footer></section>`;
 registerTranslations(pairs);return html;
}
